def _parse(version):
    """Return (core_parts, prerelease_identifiers_or_None) for a version."""
    # Build metadata is ignored for precedence.
    without_build = version.split('+', 1)[0]
    if '-' in without_build:
        core, prerelease = without_build.split('-', 1)
        pre = prerelease.split('.') if prerelease else None
    else:
        core = without_build
        pre = None
    core_parts = tuple(int(part) for part in core.split('.'))
    return core_parts, pre


def _compare_identifiers(a, b):
    a_numeric = a.isdigit()
    b_numeric = b.isdigit()
    if a_numeric and b_numeric:
        ai, bi = int(a), int(b)
        return (ai > bi) - (ai < bi)
    if a_numeric:
        return -1
    if b_numeric:
        return 1
    return (a > b) - (a < b)


def _compare_versions(a, b):
    a_core, a_pre = _parse(a)
    b_core, b_pre = _parse(b)

    if a_core != b_core:
        return (a_core > b_core) - (a_core < b_core)

    # A version with a pre-release has lower precedence than one without.
    if a_pre is None and b_pre is None:
        return 0
    if a_pre is None:
        return 1
    if b_pre is None:
        return -1

    for a_id, b_id in zip(a_pre, b_pre):
        result = _compare_identifiers(a_id, b_id)
        if result:
            return result

    return (len(a_pre) > len(b_pre)) - (len(a_pre) < len(b_pre))


def sort_versions(vs):
    """Return versions sorted by SemVer 2.0.0 precedence, lowest first.

    Ties preserve their original input order (the sort is stable).
    """
    return sorted(vs, key=cmp_to_key(_compare_versions))
